function cloneRecursive(input) {
  if (typeof input !== 'object' || input === null) {
    return input;
  }
  if (Array.isArray(input)) {
    const arr = [];
    for (let i = 0; i < input.length; i++) arr.push(cloneRecursive(input[i]));
    return arr;
  }
  return Object.entries(input).reduce((acc, [k, v]) => {
    acc[k] = cloneRecursive(v);
    return acc;
  }, {});
}

