def reverse_words(sentence):
    words = sentence.split()
    out = []
    for i in range(len(words) - 1, -1, -1):
        out.append(words[i])
    return " ".join(out)

def file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            block = fh.read(8192)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()

